物件格式:
{
  "role": <string>,
  "text_content": [
    {
      "type": "message",
      "content": "這是一段文字訊息"
    },
    {
      "type": "image",
      "content": <image uid>
    },
    {
      "type": "audio",
      "content": <audio uid>
    },
    {
      "type": "table",
      "content": {
        "columns": ["Name", "Age", "City"],
        "data": [
          ["Alice", "30", "Taipei"],
          ["Bob", "25", "Tokyo"],
          ["Chris", "22", "New York"]
        ]
      }
    }
  ],
  "reward": <string>,  // good, bad, ""
  "retry": <string> // 只有user會有，llm沒有
}

{
  "type": "message",
